import React, { useEffect, useMemo, useRef, useState } from "react";
import { useLocation } from "react-router-dom";
import { useSelector } from "react-redux";
import "../categories.css";
import "../HomeB.css";
import CategoryCard from "./CategoryCard";
import { getCategoryChips, getCategoryGroup } from "../utility/categoryGroups";
import useCategoryGroups from "../services/useCategoryGroups";

// Home page categories: group chips, a 3-column grid (first rows only until "See all"), lighter cards.
// The activity banners that used to sit inside this grid are now one "Live nearby" section (LiveNearby).
const INITIAL_COUNT = 9;

const HomeCategories = ({ handleClick }) => {
  const categories = useSelector(state => state?.categories?.data);
  const groups = useCategoryGroups();
  const location = useLocation();
  // ?categories=all (bottom nav "Categories" tab): show every category and scroll to this section
  const openAll = new URLSearchParams(location?.search).get("categories") === "all";
  const [group, setGroup] = useState("all");
  const [expanded, setExpanded] = useState(openAll);
  const sectionRef = useRef(null);

  useEffect(() => {
    if (!openAll) return;
    setGroup("all");
    setExpanded(true);
    sectionRef.current?.scrollIntoView({ behavior: "smooth", block: "start" });
  }, [openAll]);

  const visibleCategories = useMemo(
    () => (categories || []).filter((c) => c?.name !== "user"),
    [categories]
  );
  const chips = useMemo(() => getCategoryChips(visibleCategories, groups), [visibleCategories, groups]);

  const filtered = group === "all"
    ? visibleCategories
    : visibleCategories.filter((c) => getCategoryGroup(c, groups) === group);
  useEffect(() => {
    if (group !== "all" && !chips.some((c) => c.key === group)) setGroup("all");
  }, [chips, group]);

  const showAll = expanded || group !== "all";
  const shown = showAll ? filtered : filtered.slice(0, INITIAL_COUNT);
  const canToggle = group === "all" && filtered.length > INITIAL_COUNT;

  return (
    <section ref={sectionRef} className="hb-section hb-categories col-md-6 offset-md-3">
      <div className="hb-section__head">
        <h2 className="hb-section__title">Categories</h2>
        {canToggle && (
          <button type="button" className="hb-link" onClick={() => setExpanded((e) => !e)}>
            {expanded ? "Show less" : "See all"}
          </button>
        )}
      </div>

      {chips.length > 2 && (
        <div className="hb-chips" role="group" aria-label="Filter categories">
          {chips.map((chip) => (
            <button
              key={chip.key}
              type="button"
              className={`hb-chip ${group === chip.key ? "hb-chip--active" : ""}`}
              aria-pressed={group === chip.key}
              onClick={() => setGroup(chip.key)}
            >
              {chip.label}
            </button>
          ))}
        </div>
      )}

      <div className="hb-grid">
        {shown.map((category, index) => (
          <CategoryCard key={category?.id || index} category={category} handleClick={handleClick} idx={index} />
        ))}
      </div>
    </section>
  );
}

export default HomeCategories;
