  "airconditioner":   ["ac", "a/c", "cooling", "gas filling", "split ac", "window ac", "ac service", "ac repair"],
  "fridge":           ["refrigerator", "freezer", "fridge repair"],
  "washing machine":  ["washing", "washer", "dryer"],
  "carpenter":        ["furniture", "door", "darwaza", "almirah", "cupboard", "wardrobe", "bed", "mistri", "lock"],
  "painter":          ["paint", "painting", "rang", "putty", "wallpaper", "polish"],
  "pest control":     ["cockroach", "termite", "deemak", "dimak", "bed bugs", "keede", "rat", "chuha", "mosquito"],
  "cctv":             ["camera", "security camera", "cc camera"],
  "led":              ["tv", "television", "smart tv"],
  "laptop":           ["computer", "pc", "desktop", "laptop repair"],
  "water filter":     ["ro", "purifier", "water purifier", "aquaguard"],
  "bhangarwala":      ["kabadi", "kabadiwala", "raddi", "scrap", "bhangar", "kabaad"],
  "mehendi":          ["mehndi", "henna"],
  "makeup":           ["bridal", "parlour", "parlor"],
  "hair":             ["haircut", "salon", "parlour", "parlor", "hair cut"],
  "tailor":           ["blouse", "stitching", "silai", "darzi", "alteration", "kapde"],
  "embroidery":       ["zari", "kadhai", "kadai"],
  "dj":               ["sound", "speaker", "music", "dj"],
  "photographer":     ["photo", "photos", "video", "shoot", "camera man", "cameraman"],
  "event management": ["decoration", "decorator", "wedding", "shaadi", "birthday", "party"],
  "balloon":          ["birthday decoration", "balloon"],
  "event anchor":     ["host", "emcee", "mc", "anchor"],
  "choreographer":    ["dance", "dance class", "sangeet"],
  "magic":            ["magician", "jadugar"],
  "car driver":       ["driver", "chauffeur", "gaadi", "car"],
