const SMALL_WORDS = new Set(["or", "and", "of", "for", "the"]);
const UPPER_WORDS = new Set(["ac", "tv", "led", "cctv", "dj", "ro", "pc"]);

// "airconditioner (ac) technician" -> "Airconditioner (AC) Technician"
export const displayCategoryName = (name = "") =>
  String(name).trim().replace(/\s+/g, " ").toLowerCase().split(" ").map((word, i) => {
    const bare = word.replace(/[^a-z]/g, "");
    if (UPPER_WORDS.has(bare)) return word.replace(bare, bare.toUpperCase());
    if (i > 0 && SMALL_WORDS.has(bare)) return word;
    return word.replace(/[a-z]/, (c) => c.toUpperCase());
  }).join(" ");

const words = (text) => String(text || "").toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
const normalise = (text) => String(text || "").toLowerCase().trim().replace(/\s+/g, " ");

// Every typed word must be the start of some word in the name
const nameMatches = (name, query) => {
  const nameWords = words(name);
  const queryWords = words(query);
  return queryWords.length > 0 && queryWords.every((q) => nameWords.some((w) => w.startsWith(q)));
};

// A keyword that starts with what was typed, or a whole keyword inside a longer query ("ac not cooling")
const keywordMatch = (keywords, query) => {
  const q = normalise(query);
  if (q.length < 2) return null;
  return keywords.find((k) => k.startsWith(q) || (q.length > k.length && ` ${q} `.includes(` ${k} `))) || null;
};

const keywordsFor = (category) => {
  // Keywords set by an admin on the category (API) win; the built-in list is only a fallback
  if (Array.isArray(category?.keywords) && category.keywords.length) {
    return category.keywords.map((k) => normalise(k)).filter(Boolean);
  }
  const name = normalise(category?.name);
  return Object.entries(CATEGORY_KEYWORDS)
    .filter(([key]) => name.includes(key))
    .flatMap(([, list]) => list);
};

// Results: name matches first, then categories found through a keyword.
// Each result: { category, via: "name" | "keyword", keyword, examples }
export const searchCategories = (categories = [], query = "") => {
  const q = normalise(query);
  if (!q) return [];
  const byName = [];
  const byKeyword = [];
  categories.forEach((category) => {
    if (nameMatches(category?.name, q)) {
      byName.push({ category, via: "name" });
      return;
    }
    const keywords = keywordsFor(category);
    const keyword = keywordMatch(keywords, q);
    if (keyword) {
      byKeyword.push({ category, via: "keyword", keyword, examples: keywords.filter((k) => k !== keyword).slice(0, 3) });
    }
  });
  return [...byName, ...byKeyword];
};

// Split a display name into [before, match, after] for highlighting the typed text at a word start
export const highlightParts = (displayName, query) => {
  const q = normalise(query).split(" ")[0];
  if (!q) return [displayName, "", ""];
  const lower = displayName.toLowerCase();
  let index = lower.startsWith(q) ? 0 : -1;
  if (index === -1) {
    const re = new RegExp(`[^a-z0-9]${q.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}`);
    const m = lower.match(re);
    if (m) index = m.index + 1;
  }
  if (index === -1) return [displayName, "", ""];
  return [displayName.slice(0, index), displayName.slice(index, index + q.length), displayName.slice(index + q.length)];
};

// Categories with the same name (e.g. two "carpenter" entries) are shown once
export const uniqueByName = (categories = []) => {
  const seen = new Set();
  return categories.filter((c) => {
    const key = normalise(c?.name);
    if (!key || key === "user" || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
};

// Recently opened categories (separate from the analytics list "searchCategoryList", which also holds half-typed words)
const RECENT_KEY = "recentSearchCategories";
const RECENT_MAX = 5;

export const getRecentCategoryIds = () => {
  try { return JSON.parse(localStorage.getItem(RECENT_KEY)) || []; } catch (e) { return []; }
};
export const addRecentCategory = (id) => {
  if (!id) return;
  try {
    const list = [id, ...getRecentCategoryIds().filter((x) => x !== id)].slice(0, RECENT_MAX);
    localStorage.setItem(RECENT_KEY, JSON.stringify(list));
  } catch (e) { /* storage unavailable: no recents */ }
};
export const clearRecentCategories = () => {
  try { localStorage.removeItem(RECENT_KEY); } catch (e) { /* ignore */ }
};

