import { useEffect, useRef, useState } from "react";
import axios from "axios";
import OtpComponent from "../components/OtpComponent";
import { encryptPassword, getConfig, getConstant, handleErrorResponse, handleHeader } from "../services/functions";
import { useDispatch, useSelector } from "react-redux";
import H from "../components/H";
import { verifyOtpAction } from "../redux/slices/authSlice";
import { listCategoryAction } from "../redux/slices/categoriesSlice";
import { showAlert } from "../redux/slices/alertSlice";
import { spinner } from "../redux/slices/spinnerSlice";
import SumVerification from "../components/SumVerification";
import { BASE_URL } from "../utility/path";

// Must match OTP_RESEND_SECONDS on the server (minimum gap between OTPs to the same number)
const RESEND_SECONDS = 30;

const EnterOtp = ({ nextStep, previousStep, handleChangeOtp, state, vendor }) => {
  const authData = useSelector(state => state?.auth?.data);
  const [showTransition, setShowTransition] = useState(false);
  const dispatch = useDispatch();
  const [verified, setVerified] = useState(true);

  const [code, setCode] = useState("");               // digits currently in the boxes
  const [submitting, setSubmitting] = useState(false);
  const [resetKey, setResetKey] = useState(0);        // bump to clear the boxes
  const [attemptsLeft, setAttemptsLeft] = useState(null);
  const [resendIn, setResendIn] = useState(RESEND_SECONDS); // an OTP was just sent when this screen opens
  const [resending, setResending] = useState(false);
  const submittingRef = useRef(false);

  // countdown for "Resend OTP"
  useEffect(() => {
    if (resendIn <= 0) return undefined;
    const timer = setTimeout(() => setResendIn((s) => s - 1), 1000);
    return () => clearTimeout(timer);
  }, [resendIn]);

  const onOtpChange = (name, value) => {
    setCode(value);
    if (handleChangeOtp && value) handleChangeOtp(name, value);
  };

  const submit = async (otp) => {
    if (submittingRef.current || !otp || otp.length !== 4) return;
    submittingRef.current = true;
    setSubmitting(true);
    try {
      // OTP is RSA-encrypted with the same public key as passwords; the server decrypts it (otpEncrypted flag)
      const result = await dispatch(verifyOtpAction({ ...state, otp: encryptPassword(otp), otpEncrypted: true, locationPathname: location?.pathname, vendor: vendor }));
      if (result?.meta?.requestStatus === "rejected") {
        // wrong/expired code: clear the boxes so the user can type again; the error is shown as an alert
        const left = result?.payload?.attemptsLeft;
        setAttemptsLeft(typeof left === "number" ? left : null);
        setResetKey((k) => k + 1);
      } else {
        dispatch(listCategoryAction(authData));
      }
    } finally {
      submittingRef.current = false;
      setSubmitting(false);
    }
  };

  const Continue = e => {
    e.preventDefault();
    submit(code);
  };

  // Request a new OTP. Calls the API directly (not verifyMobileAction) so an error such as
  // "please wait" doesn't log the user out or move them off this screen.
  const resendOtp = async () => {
    if (resendIn > 0 || resending) return;
    setResending(true);
    dispatch(spinner(true));
    const url = state?.action === "delete_account" ? `${BASE_URL}/api/users/verifyMobilea` : `${BASE_URL}/api/users/verifyMobile`;
    try {
      await axios.post(url, { ...state, otp: "", locationPathname: location?.pathname, vendor: vendor }, getConfig());
      dispatch(showAlert({ message: "A new OTP has been sent.", success: true }));
      setAttemptsLeft(null);
      setResetKey((k) => k + 1);
      setResendIn(RESEND_SECONDS);
    } catch (error) {
      handleErrorResponse(error, dispatch); // shows the server's message
      const retryAfter = Number(error?.response?.data?.retryAfter);
      if (retryAfter > 0) setResendIn(Math.min(Math.ceil(retryAfter), 15 * 60));
    } finally {
      dispatch(spinner(false));
      setResending(false);
    }
  };

  useEffect(()=>{
    setShowTransition(true);
    handleHeader({...getConstant("VERIFY_OTP")},dispatch);
    return ()=>{setShowTransition(false)}
  },[]);

  const handleVerification = (isVerified) => {
    if (isVerified) {
      handleHeader({...getConstant("VERIFY_OTP")},dispatch);
      setVerified(true);
    } else {
      setVerified(false);
    }
  };

  const formatSeconds = (s) => (s >= 60 ? `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}` : `${s}s`);

  return (
    <div className={`show-transition ${showTransition ? "show" : ""}`}>
      {!verified && <H value={"Verify Captcha"}/>}
      {verified && <H value={"Verify OTP"}/>}

      {!verified && <SumVerification onVerify={handleVerification}/>}
      {verified && (
        <OtpComponent
          handleChangeOtp={onOtpChange}
          onComplete={(otp) => submit(otp)}   // submit as soon as all 4 digits are in
          resetKey={resetKey}
          disabled={submitting}
        />
      )}

      {verified && attemptsLeft !== null && (
        <p className={attemptsLeft > 0 ? "text-danger mb-2" : "text-danger mb-2 fw-bold"}>
          <small>{attemptsLeft > 0 ? `${attemptsLeft} attempt${attemptsLeft === 1 ? "" : "s"} left` : "No attempts left. Please request a new OTP."}</small>
        </p>
      )}

      {verified && !vendor && (
        <p className="mb-2">
          <small>
            {resendIn > 0
              ? <span className="text-muted">Resend OTP in {formatSeconds(resendIn)}</span>
              : <a href="#" className="link-primary" onClick={(e) => { e.preventDefault(); resendOtp(); }}>{resending ? "Sending…" : "Resend OTP"}</a>}
          </small>
        </p>
      )}

      {verified && <button className="btn btn-primary m-0" onClick={Continue} disabled={submitting || !code || code.length !== 4}>{submitting ? "Verifying…" : "Submit"}</button>}
      {<button className="btn btn-primary m-2" onClick={previousStep}>Back</button>}
    </div>
  );
}

export default EnterOtp;
