import React, { useEffect, useRef, useState } from 'react';

// 4-digit OTP input.
// - One list of digits drives both what's shown and what's reported, so they can't get out of sync.
// - Backspace clears and moves back, arrow keys move, pasting a full code fills every box.
// - inputMode="numeric" shows the number keypad; autoComplete="one-time-code" lets the phone offer the code from the SMS.
// Props:
//   handleChangeOtp(name, value): called with ('otp', current digits) on every change
//   onComplete(code): optional, called once all boxes are filled
//   resetKey: change it to clear the boxes and focus the first one (e.g. after a wrong code or a resend)
//   disabled: optional
const OTP_LENGTH = 4;

const OtpComponent = ({ handleChangeOtp, onComplete, resetKey, disabled }) => {
  const [digits, setDigits] = useState(Array(OTP_LENGTH).fill(''));
  const inputRefs = useRef([]);

  const focusBox = (index) => {
    const box = inputRefs.current[Math.max(0, Math.min(index, OTP_LENGTH - 1))];
    if (box) { box.focus(); box.select(); }
  };

  const update = (newDigits) => {
    setDigits(newDigits);
    const code = newDigits.join('');
    if (handleChangeOtp) handleChangeOtp('otp', code);
    if (onComplete && newDigits.every((d) => d !== '')) onComplete(code);
  };

  // clear and focus the first box on mount and whenever resetKey changes
  useEffect(() => {
    setDigits(Array(OTP_LENGTH).fill(''));
    if (handleChangeOtp) handleChangeOtp('otp', '');
    focusBox(0);
  }, [resetKey]);

  // Fill boxes from `index` onward with the digits in `text` (typing, paste or SMS autofill)
  const fillFrom = (index, text) => {
    const incoming = String(text || '').replace(/\D/g, '');
    if (!incoming) return;
    // A full code (paste/autofill) always starts at the first box
    const start = incoming.length >= OTP_LENGTH ? 0 : index;
    const newDigits = [...digits];
    let pos = start;
    for (const ch of incoming) {
      if (pos >= OTP_LENGTH) break;
      newDigits[pos] = ch;
      pos++;
    }
    update(newDigits);
    focusBox(pos >= OTP_LENGTH ? OTP_LENGTH - 1 : pos);
  };

  const handleChange = (e, index) => {
    const value = e.target.value;
    if (value === '') {
      const newDigits = [...digits];
      newDigits[index] = '';
      update(newDigits);
      return;
    }
    // the box may briefly hold the old digit plus the new one: keep only what was typed
    const typed = value.length > 1 && digits[index] && value.startsWith(digits[index]) ? value.slice(1) : value;
    fillFrom(index, typed);
  };

  const handleKeyDown = (e, index) => {
    if (e.key === 'Backspace') {
      e.preventDefault();
      const newDigits = [...digits];
      if (newDigits[index]) {
        newDigits[index] = '';
        update(newDigits);
      } else if (index > 0) {
        newDigits[index - 1] = '';
        update(newDigits);
        focusBox(index - 1);
      }
    } else if (e.key === 'Delete') {
      e.preventDefault();
      const newDigits = [...digits];
      newDigits[index] = '';
      update(newDigits);
    } else if (e.key === 'ArrowLeft') {
      e.preventDefault();
      focusBox(index - 1);
    } else if (e.key === 'ArrowRight') {
      e.preventDefault();
      focusBox(index + 1);
    }
  };

  const handlePaste = (e, index) => {
    e.preventDefault();
    fillFrom(index, e.clipboardData?.getData('text'));
  };

  return (
    <div className="input-group mb-3">
      {digits.map((digit, index) => (
        <input
          key={index}
          ref={(el) => { inputRefs.current[index] = el; }}
          className="form-control otpInput bg-light"
          type="text"
          inputMode="numeric"
          pattern="[0-9]*"
          autoComplete={index === 0 ? 'one-time-code' : 'off'}
          maxLength={index === 0 ? OTP_LENGTH : 1}
          placeholder="-"
          aria-label={`OTP digit ${index + 1} of ${OTP_LENGTH}`}
          value={digit}
          disabled={disabled}
          onChange={(e) => handleChange(e, index)}
          onKeyDown={(e) => handleKeyDown(e, index)}
          onPaste={(e) => handlePaste(e, index)}
          onFocus={(e) => e.target.select()}
        />
      ))}
    </div>
  );
};

export default OtpComponent;
