import { useEffect, useState } from "react";
import axios from "axios";
import { BASE_URL } from "../utility/path";

// Active category groups from the API (admin-managed), in display order: [{ id, name, priority }].
// Loaded once per app session and shared; the last list is kept in localStorage so chips show instantly.
// Returns [] until loaded or if the API isn't available, and the callers then fall back to built-in groups.
const STORAGE_KEY = "categoryGroups";
let cache = null;
let request = null;

const readStored = () => {
  try { return JSON.parse(localStorage.getItem(STORAGE_KEY)) || []; } catch (e) { return []; }
};

export const loadCategoryGroups = () => {
  if (cache) return Promise.resolve(cache);
  if (!request) {
    request = axios.get(`${BASE_URL}/api/categorygroups/list`)
      .then(({ data }) => {
        cache = Array.isArray(data) ? data.map((g) => ({ id: g.id || g._id, name: g.name, priority: g.priority })) : [];
        try { localStorage.setItem(STORAGE_KEY, JSON.stringify(cache)); } catch (e) { /* ignore */ }
        return cache;
      })
      .catch(() => { request = null; return readStored(); });
  }
  return request;
};

// Call after an admin changes groups, so the next screen loads the new list
export const resetCategoryGroups = () => { cache = null; request = null; };

const useCategoryGroups = () => {
  const [groups, setGroups] = useState(() => cache || readStored());
  useEffect(() => {
    let active = true;
    loadCategoryGroups().then((list) => { if (active) setGroups(list); });
    return () => { active = false; };
  }, []);
  return groups;
};

export default useCategoryGroups;
