import { useEffect, useMemo, useRef, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import NavBar from "../components/Navigation/NavBar";
import { addCategoryAction, listCategoryAdminAction } from "../redux/slices/categoriesSlice";
import MainContainer from "../components/MainContainer";
import { getConfig, getConstant, handleErrorResponse, handleHeader } from "../services/functions";
import { spinner } from "../redux/slices/spinnerSlice";
import { showAlert } from "../redux/slices/alertSlice";
import axios from "axios";
import { BASE_URL, CHANGE_CATEGORY_ICON_PATH } from "../utility/path";
import { useNavigate } from "react-router";
import IconList from "../components/IconList";
import { resetCategoryGroups } from "../services/useCategoryGroups";
import { displayCategoryName } from "../utility/categorySearch";
import "../AdminCategories.css";

// Admin page: Categories tab (find, filter, switch on/off, edit in a panel) and Groups tab (the home page chips).

const KEYWORDS_MAX = 30;
const KEYWORD_MAX_LEN = 30;

const groupIdOf = (group) => (group && typeof group === "object" ? String(group.id || group._id || "") : String(group || ""));
const cleanKeyword = (k) => String(k || "").toLowerCase().trim().replace(/\s+/g, " ");
const sameList = (a = [], b = []) => a.length === b.length && a.every((x, i) => x === b[i]);
const byPriority = (a, b) => (Number(a.priority) - Number(b.priority)) || String(a.name).localeCompare(String(b.name));

const Thumb = ({ photo }) => {
  const [failed, setFailed] = useState(false);
  return (
    <span className="ac-item__img" aria-hidden="true">
      {photo && !failed ? <img src={photo} alt="" onError={() => setFailed(true)} /> : <i className="fa fa-briefcase" />}
    </span>
  );
};

const Switch = ({ checked, onChange, label, disabled }) => (
  <span className="ac-switch">
    <input type="checkbox" role="switch" aria-label={label} checked={!!checked} disabled={disabled} onChange={(e) => onChange(e.target.checked)} />
    <span className="ac-switch__track" aria-hidden="true" />
  </span>
);

// Slide-up panel for adding or editing a category
const CategoryPanel = ({ mode, category, groups, onClose, onSave, onChangeIcon }) => {
  const initial = useMemo(() => ({
    name: category?.name || "",
    group: groupIdOf(category?.group),
    active: category ? category.active !== false : true,
    keywords: Array.isArray(category?.keywords) ? category.keywords.map(cleanKeyword).filter(Boolean) : [],
  }), [category]);
  const [name, setName] = useState(initial.name);
  const [group, setGroup] = useState(initial.group);
  const [active, setActive] = useState(initial.active);
  const [keywords, setKeywords] = useState(initial.keywords);
  const [kwInput, setKwInput] = useState("");
  const [saving, setSaving] = useState(false);
  const nameRef = useRef(null);

  useEffect(() => { nameRef.current?.focus(); }, []);

  const addKeywords = (text) => {
    const words = String(text || "").split(",").map(cleanKeyword).filter((k) => k && k.length <= KEYWORD_MAX_LEN);
    if (!words.length) return;
    setKeywords((current) => {
      const next = [...current];
      words.forEach((w) => { if (!next.includes(w) && next.length < KEYWORDS_MAX) next.push(w); });
      return next;
    });
  };

  // Keywords including whatever is still typed in the box
  const finalKeywords = () => {
    const pending = String(kwInput || "").split(",").map(cleanKeyword).filter((k) => k && k.length <= KEYWORD_MAX_LEN);
    const next = [...keywords];
    pending.forEach((w) => { if (!next.includes(w) && next.length < KEYWORDS_MAX) next.push(w); });
    return next;
  };

  const changes = (() => {
    const c = [];
    const n = name.trim().toLowerCase();
    if (mode === "edit" && n && n !== initial.name) c.push("name");
    if (group !== initial.group) c.push("group");
    if (mode === "edit" && active !== initial.active) c.push("active");
    if (!sameList(finalKeywords(), initial.keywords)) c.push("keywords");
    return c;
  })();
  const canSave = mode === "add" ? !!name.trim() : changes.length > 0;

  const close = () => {
    if ((changes.length || (mode === "add" && name.trim())) && !window.confirm("Discard your changes?")) return;
    onClose();
  };

  useEffect(() => {
    const onKey = (e) => { if (e.key === "Escape") close(); };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  });

  const save = async () => {
    if (!canSave || saving) return;
    setSaving(true);
    const ok = await onSave({ name: name.trim().toLowerCase(), group: group || null, active, keywords: finalKeywords(), changes });
    setSaving(false);
    if (ok) onClose();
  };

  const isNew = (k) => !initial.keywords.includes(k);
  const title = mode === "add" ? "New category" : displayCategoryName(category?.name);

  return (
    <div className="ac-backdrop" onMouseDown={(e) => { if (e.target === e.currentTarget) close(); }}>
      <div className="ac-panel" role="dialog" aria-modal="true" aria-label={mode === "add" ? "Add category" : "Edit category"}>
        <div className="ac-panel__grab" aria-hidden="true"><span /></div>
        <div className="ac-panel__head">
          {mode === "edit" && <Thumb photo={category?.photo} />}
          <div className="ac-panel__title">
            <strong>{title}</strong>
            {mode === "edit"
              ? <button type="button" className="ac-linkbtn" onClick={() => onChangeIcon(category)}>Change icon</button>
              : <small className="text-muted">You can add its icon after saving.</small>}
          </div>
          <button type="button" className="ac-icon-btn" aria-label="Close" onClick={close}><i className="fa fa-times" aria-hidden="true" /></button>
        </div>

        <div className="ac-panel__body">
          <label className="ac-field">Name
            <input ref={nameRef} className="ac-input" type="text" value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. plumber" />
          </label>

          <label className="ac-field">Group
            <select className="ac-select" value={group} onChange={(e) => setGroup(e.target.value)}>
              <option value="">No group (shows under "Other")</option>
              {groups.map((g) => (
                <option key={g.id} value={g.id}>{g.name}{g.active ? "" : " (off)"}</option>
              ))}
            </select>
          </label>

          {mode === "edit" && (
            <div className="ac-active-line">
              <span className="ac-field">Active<small>Shown to users on the home page and in search</small></span>
              <Switch checked={active} onChange={setActive} label="Active" />
            </div>
          )}

          <div className="ac-field">
            <span>Search keywords <small>· {keywords.length}</small></span>
            <small>Words people type when looking for this — local words or problems. Press Enter after each.</small>
            <div className="ac-keywords" onClick={(e) => e.currentTarget.querySelector("input")?.focus()}>
              {keywords.map((k) => (
                <span key={k} className={`ac-kw ${isNew(k) ? "ac-kw--new" : ""}`}>
                  {k}
                  <button type="button" aria-label={`Remove ${k}`} onClick={() => setKeywords(keywords.filter((x) => x !== k))}>×</button>
                </span>
              ))}
              <input
                type="text"
                aria-label="Add a keyword"
                placeholder={keywords.length >= KEYWORDS_MAX ? "Keyword limit reached" : "Add a keyword, press Enter"}
                disabled={keywords.length >= KEYWORDS_MAX}
                value={kwInput}
                onChange={(e) => {
                  const v = e.target.value;
                  if (v.includes(",")) { addKeywords(v); setKwInput(""); } else setKwInput(v);
                }}
                onKeyDown={(e) => {
                  if (e.key === "Enter") { e.preventDefault(); addKeywords(kwInput); setKwInput(""); }
                  else if (e.key === "Backspace" && !kwInput && keywords.length) setKeywords(keywords.slice(0, -1));
                }}
              />
            </div>
          </div>
        </div>

        <div className="ac-panel__foot">
          <span className="ac-panel__status" aria-live="polite">
            {mode === "add" ? (name.trim() ? "Ready to add" : "Enter a name")
              : changes.length ? `${changes.length} change${changes.length === 1 ? "" : "s"} · not saved yet` : "No changes yet"}
          </span>
          <button type="button" className="ac-btn ac-btn--light" onClick={close}>Cancel</button>
          <button type="button" className="ac-btn ac-btn--dark" disabled={!canSave || saving} onClick={save}>
            {saving ? "Saving…" : mode === "add" ? "Add" : "Save"}
          </button>
        </div>
      </div>
    </div>
  );
};

const Category = () => {
  const categoriesData = useSelector(state => state?.categories?.data);
  const authData = useSelector(state => state?.auth?.data);
  const dispatch = useDispatch();
  const navigate = useNavigate();

  const [categories, setCategories] = useState(Array.isArray(categoriesData) ? categoriesData : []);
  const [groups, setGroups] = useState([]);
  const [tab, setTab] = useState("categories");
  const [query, setQuery] = useState("");
  const [groupFilter, setGroupFilter] = useState("all");
  const [showInactive, setShowInactive] = useState(true);
  const [panel, setPanel] = useState(null);          // { mode: "edit" | "add", category }
  const [busy, setBusy] = useState({});              // ids being switched on/off
  const [renaming, setRenaming] = useState(null);    // { id, name }
  const [newGroupName, setNewGroupName] = useState("");

  useEffect(() => {
    if (Array.isArray(categoriesData)) setCategories(categoriesData);
  }, [categoriesData]);

  useEffect(() => {
    handleHeader({ ...getConstant("CATEGORY") }, dispatch);
    dispatch(listCategoryAdminAction({}));
    loadGroups();
  }, []);

  const alert = (message, success = true) => dispatch(showAlert({ message, success }));

  // ---------- groups ----------
  const loadGroups = async () => {
    try {
      const { data } = await axios.get(`${BASE_URL}/api/categorygroups/lista`, getConfig());
      setGroups((Array.isArray(data) ? data : []).map((g) => ({ id: g.id || g._id, name: g.name, priority: g.priority, active: g.active })).sort(byPriority));
    } catch (error) {
      handleErrorResponse(error, dispatch);
    }
  };

  const updateGroup = async (id, changes, message) => {
    try {
      dispatch(spinner(true));
      await axios.put(`${BASE_URL}/api/categorygroups/update`, { id, ...changes }, getConfig());
      dispatch(spinner(false));
      if (message) alert(message);
      resetCategoryGroups();
      await loadGroups();
      return true;
    } catch (error) {
      dispatch(spinner(false));
      handleErrorResponse(error, dispatch);
      return false;
    }
  };

  // Swap a group with its neighbour, then renumber all groups 10, 20, 30… so the order stays clean
  const moveGroup = async (index, direction) => {
    const order = [...groups];
    const target = index + direction;
    if (target < 0 || target >= order.length) return;
    [order[index], order[target]] = [order[target], order[index]];
    try {
      dispatch(spinner(true));
      for (let i = 0; i < order.length; i++) {
        const priority = (i + 1) * 10;
        if (Number(order[i].priority) !== priority) {
          await axios.put(`${BASE_URL}/api/categorygroups/update`, { id: order[i].id, priority }, getConfig());
        }
      }
      dispatch(spinner(false));
    } catch (error) {
      dispatch(spinner(false));
      handleErrorResponse(error, dispatch);
    }
    resetCategoryGroups();
    loadGroups();
  };

  const addGroup = async (e) => {
    e.preventDefault();
    const name = newGroupName.trim();
    if (!name) return;
    // New groups go before "Other" if there is one, otherwise at the end
    const other = groups.find((g) => String(g.name).toLowerCase() === "other");
    const rest = groups.filter((g) => g !== other);
    const priority = rest.length ? Math.max(...rest.map((g) => Number(g.priority) || 0)) + 1 : 1;
    try {
      dispatch(spinner(true));
      const { data } = await axios.post(`${BASE_URL}/api/categorygroups/add`, { name, priority }, getConfig());
      dispatch(spinner(false));
      alert(data?.message || "Group added!!");
      setNewGroupName("");
      resetCategoryGroups();
      loadGroups();
    } catch (error) {
      dispatch(spinner(false));
      handleErrorResponse(error, dispatch);
    }
  };

  // ---------- categories ----------
  const setActive = async (ct, next) => {
    setBusy((b) => ({ ...b, [ct.id]: true }));
    setCategories((list) => list.map((c) => (c.id === ct.id ? { ...c, active: next } : c)));
    try {
      await axios.put(`${BASE_URL}/api/categories/updateStatus`, { uid: authData?.id, cid: ct.id, c_active: !next, n_active: next }, getConfig());
      alert(`${displayCategoryName(ct.name)} is now ${next ? "active" : "inactive"}.`);
      return true;
    } catch (error) {
      setCategories((list) => list.map((c) => (c.id === ct.id ? { ...c, active: !next } : c)));
      handleErrorResponse(error, dispatch);
      return false;
    } finally {
      setBusy((b) => ({ ...b, [ct.id]: false }));
    }
  };

  const saveCategory = async ({ name, group, active, keywords, changes }) => {
    if (panel?.mode === "add") {
      const result = await dispatch(addCategoryAction({ name, group, keywords }));
      dispatch(listCategoryAdminAction({}));
      return result?.meta?.requestStatus === "fulfilled";
    }
    const ct = panel?.category;
    const body = { id: ct.id };
    if (changes.includes("name")) body.name = name;
    if (changes.includes("group")) body.group = group;
    if (changes.includes("keywords")) body.keywords = keywords;
    try {
      dispatch(spinner(true));
      let updated = ct;
      if (Object.keys(body).length > 1) {
        const { data } = await axios.put(`${BASE_URL}/api/categories/update`, body, getConfig());
        updated = { ...ct, name: data?.name ?? ct.name, group: data?.group ?? null, keywords: data?.keywords ?? ct.keywords };
      }
      setCategories((list) => list.map((c) => (c.id === ct.id ? { ...c, ...updated } : c)));
      dispatch(spinner(false));
      if (changes.includes("active")) {
        const ok = await setActive(updated, active);
        if (!ok) return false;
      } else {
        alert("Category updated!!");
      }
      return true;
    } catch (error) {
      dispatch(spinner(false));
      handleErrorResponse(error, dispatch);
      return false;
    }
  };

  const changeIcon = (ct) => navigate(CHANGE_CATEGORY_ICON_PATH, { state: { categoryId: ct?.id, categoryName: ct?.name } });

  // ---------- derived ----------
  const realCategories = categories.filter((c) => c?.name && c.name !== "user");
  const groupName = (ct) => groups.find((g) => String(g.id) === groupIdOf(ct.group))?.name;
  const countFor = (id) => realCategories.filter((c) => groupIdOf(c.group) === String(id)).length;
  const ungroupedCount = realCategories.filter((c) => !groupName(c)).length;

  const q = query.trim().toLowerCase();
  const shown = realCategories
    .filter((c) => showInactive || c.active !== false)
    .filter((c) => groupFilter === "all" || (groupFilter === "none" ? !groupName(c) : groupIdOf(c.group) === groupFilter))
    .filter((c) => !q || c.name.toLowerCase().includes(q))
    .sort((a, b) => displayCategoryName(a.name).localeCompare(displayCategoryName(b.name)));

  const chips = [
    { key: "all", label: "All" },
    ...groups.map((g) => ({ key: String(g.id), label: g.name })),
    ...(ungroupedCount ? [{ key: "none", label: "No group" }] : []),
  ];

  return (
    <>
      <NavBar />
      <MainContainer>
        <div className="ac-page">
          <div className="ac-top">
            <div className="ac-tabs" role="tablist">
              <button type="button" role="tab" aria-selected={tab === "categories"} className={`ac-tab ${tab === "categories" ? "ac-tab--active" : ""}`} onClick={() => setTab("categories")}>Categories · {realCategories.length}</button>
              <button type="button" role="tab" aria-selected={tab === "groups"} className={`ac-tab ${tab === "groups" ? "ac-tab--active" : ""}`} onClick={() => setTab("groups")}>Groups · {groups.length}</button>
            </div>

            {tab === "categories" && (
              <>
                <div className="ac-row-flex">
                  <label className="ac-search">
                    <i className="fa fa-search" aria-hidden="true" />
                    <input type="text" aria-label="Find a category" placeholder="Find a category" value={query} onChange={(e) => setQuery(e.target.value)} />
                  </label>
                  <button type="button" className="ac-btn ac-btn--dark" onClick={() => setPanel({ mode: "add", category: null })}>
                    <i className="fa fa-plus" aria-hidden="true" /> Add
                  </button>
                </div>
                <div className="ac-chips" role="group" aria-label="Filter by group">
                  {chips.map((c) => (
                    <button key={c.key} type="button" className={`ac-chip ${groupFilter === c.key ? "ac-chip--active" : ""}`} aria-pressed={groupFilter === c.key} onClick={() => setGroupFilter(c.key)}>{c.label}</button>
                  ))}
                </div>
                <label className="ac-toggle-line">
                  Show inactive categories
                  <Switch checked={showInactive} onChange={setShowInactive} label="Show inactive categories" />
                </label>
              </>
            )}
          </div>

          {tab === "categories" && (
            <>
              <div className="ac-list">
                {shown.map((ct) => {
                  const gName = groupName(ct);
                  const kw = ct?.keywords?.length || 0;
                  return (
                    <div key={ct.id} className={`ac-item ${ct.active === false ? "ac-item--inactive" : ""}`}>
                      <Thumb photo={ct.photo} />
                      <button type="button" className="ac-item__text" onClick={() => setPanel({ mode: "edit", category: ct })} aria-label={`Edit ${displayCategoryName(ct.name)}`}>
                        <span className="ac-item__name">{displayCategoryName(ct.name)}</span>
                        <span className="ac-item__meta">
                          <span className={`ac-tag ${gName ? "" : "ac-tag--none"}`}>{gName || "No group"}</span>
                          {kw ? `${kw} keyword${kw === 1 ? "" : "s"}` : "No keywords"}
                        </span>
                      </button>
                      <Switch checked={ct.active !== false} disabled={!!busy[ct.id]} onChange={(next) => setActive(ct, next)} label={`${displayCategoryName(ct.name)} active`} />
                      <button type="button" className="ac-icon-btn" aria-label={`Edit ${displayCategoryName(ct.name)}`} onClick={() => setPanel({ mode: "edit", category: ct })}>
                        <i className="fa fa-pencil" aria-hidden="true" />
                      </button>
                    </div>
                  );
                })}
                {!shown.length && <p className="ac-empty">No categories match.</p>}
              </div>
              {/* <IconList /> */}
            </>
          )}

          {tab === "groups" && (
            <div className="ac-list">
              <p className="ac-hint">Groups are the chips on the home page, in this order. Switch one off to hide its chip; its categories move to "Other".</p>
              {groups.map((g, i) => (
                <div key={g.id} className={`ac-group ${g.active ? "" : "ac-group--off"}`}>
                  <div className="ac-group__arrows">
                    <button type="button" className="ac-arrow" aria-label={`Move ${g.name} up`} disabled={i === 0} onClick={() => moveGroup(i, -1)}><i className="fa fa-chevron-up" aria-hidden="true" /></button>
                    <button type="button" className="ac-arrow" aria-label={`Move ${g.name} down`} disabled={i === groups.length - 1} onClick={() => moveGroup(i, 1)}><i className="fa fa-chevron-down" aria-hidden="true" /></button>
                  </div>
                  {renaming?.id === g.id ? (
                    <form className="ac-group__rename" onSubmit={async (e) => {
                      e.preventDefault();
                      if (renaming.name.trim() && renaming.name.trim() !== g.name && await updateGroup(g.id, { name: renaming.name.trim() }, "Group renamed!!")) setRenaming(null);
                    }}>
                      <input className="ac-input" aria-label="Group name" autoFocus value={renaming.name} onChange={(e) => setRenaming({ id: g.id, name: e.target.value })} />
                      <button type="submit" className="ac-btn ac-btn--dark ac-btn--sm" disabled={!renaming.name.trim() || renaming.name.trim() === g.name}>Save</button>
                      <button type="button" className="ac-btn ac-btn--light ac-btn--sm" onClick={() => setRenaming(null)}>Cancel</button>
                    </form>
                  ) : (
                    <>
                      <div className="ac-group__text">
                        <span className="ac-group__name">{g.name}</span>
                        <span className="ac-group__count">{countFor(g.id)} {countFor(g.id) === 1 ? "category" : "categories"}{g.active ? "" : " · hidden"}</span>
                      </div>
                      <button type="button" className="ac-icon-btn" aria-label={`Rename ${g.name}`} onClick={() => setRenaming({ id: g.id, name: g.name })}><i className="fa fa-pencil" aria-hidden="true" /></button>
                      <Switch checked={g.active} label={`Show ${g.name}`} onChange={(next) => updateGroup(g.id, { active: next }, `${g.name} ${next ? "shown" : "hidden"} on the home page.`)} />
                    </>
                  )}
                </div>
              ))}
              {!groups.length && <p className="ac-empty">No groups yet. Add one below, or run the seed script.</p>}
              {ungroupedCount > 0 && <p className="ac-hint">{ungroupedCount} {ungroupedCount === 1 ? "category has" : "categories have"} no group and show under "Other".</p>}
              <form className="ac-add-group" onSubmit={addGroup}>
                <input className="ac-input" aria-label="New group name" placeholder="New group name" value={newGroupName} onChange={(e) => setNewGroupName(e.target.value)} />
                <button type="submit" className="ac-btn ac-btn--dark" disabled={!newGroupName.trim()}>Add group</button>
              </form>
            </div>
          )}
        </div>
      </MainContainer>

      {panel && (
        <CategoryPanel
          key={panel.category?.id || "new"}
          mode={panel.mode}
          category={panel.category}
          groups={groups}
          onClose={() => setPanel(null)}
          onSave={saveCategory}
          onChangeIcon={(ct) => { setPanel(null); changeIcon(ct); }}
        />
      )}
    </>
  );
}

export default Category;
