import { useEffect, useState } from "react";
import { useDispatch } from "react-redux";
import axios from "axios";
import { BASE_URL } from "../utility/path";
import { getConfig } from "../services/functions";
import { detailsAction } from "../redux/slices/detailsSlice";
import { getCategoryColor } from "../utility/colorForCategoryUtils";
import DetailsModel from "./DetailsModel";
import "../HomeB.css";

// "Top rated near you": the nearest active professionals (same /api/users/list call the home page uses),
// keeping those with at least one rating, sorted by their real average rating. Hidden if none are rated.
const FETCH_COUNT = 20;
const SHOW_COUNT = 6;

const averageOf = (ratings = []) => {
  const values = ratings.map((r) => Number(r?.rating)).filter((n) => n >= 1 && n <= 5);
  if (!values.length) return null;
  return Math.round((values.reduce((a, b) => a + b, 0) / values.length) * 10) / 10;
};

const TopRated = () => {
  const dispatch = useDispatch();
  const [pros, setPros] = useState([]);

  useEffect(() => {
    let cancelled = false;
    const location = localStorage.getItem("location")
      ? JSON.parse(localStorage.getItem("location"))
      : { latitude: -1, longitude: -1 };

    axios.post(`${BASE_URL}/api/users/list`, { ...location, limit: FETCH_COUNT, skip: 0 }, getConfig())
      .then(({ data }) => {
        if (cancelled) return;
        const rated = (data?.user || [])
          .map((u) => ({ user: u, avg: averageOf(u?.ratingByOthers), count: u?.ratingByOthers?.length || 0 }))
          .filter((p) => p.avg !== null)
          .sort((a, b) => b.avg - a.avg || b.count - a.count)
          .slice(0, SHOW_COUNT);
        setPros(rated);
      })
      .catch(() => { if (!cancelled) setPros([]); }); // section simply stays hidden

    return () => { cancelled = true; };
  }, []);

  const openDetails = (userId) => {
    if (!userId) return;
    dispatch(detailsAction({ otherUserId: userId }));
    const modalElement = document.getElementById("detailsModal");
    if (modalElement) {
      document.getElementById("header")?.classList?.add("hidden");
      $(modalElement).modal("show"); // Bootstrap 4, same as Cards.js
      modalElement.focus();
    }
  };

  return (
    <>
      {pros.length > 0 && (
        <section className="hb-section col-md-6 offset-md-3">
          <h2 className="hb-section__title hb-section__title--spaced">Top rated near you</h2>
          <div className="hb-pros">
            {pros.map(({ user, avg, count }, i) => {
              const colors = getCategoryColor(i);
              return (
                <div key={user?.id || i} className="hb-pro">
                  <div className="hb-pro__photo" style={{ background: colors.bg }}>
                    {user?.profilePhoto
                      ? <img src={user.profilePhoto} alt="" loading="lazy" onError={(e) => { e.currentTarget.style.display = "none"; }} />
                      : <i className="fa fa-user" style={{ color: colors.text }} aria-hidden="true" />}
                  </div>
                  <div className="hb-pro__body">
                    <span className="hb-pro__name">{user?.name}</span>
                    <span className="hb-pro__cat">{user?.category?.[0]?.name}</span>
                    <div className="hb-pro__foot">
                      <span className="hb-pro__rating" aria-label={`Rated ${avg} out of 5 by ${count} ${count === 1 ? "person" : "people"}`}>
                        <i className="fa fa-star" aria-hidden="true" /> {avg.toFixed(1)}
                      </span>
                      <button type="button" className="hb-pro__btn" onClick={() => openDetails(user?.id)}>Contact</button>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </section>
      )}
      <DetailsModel></DetailsModel>
    </>
  );
};

export default TopRated;
