// True inside the Android (Cordova) app. Kept in its own file with no imports so utility/path*.js can use it
// without importing services/functions.js (that created an import loop: path -> functions -> headerSlice -> path,
// which crashed with "Cannot access 'HOME_PATH' before initialization" depending on load order).
export function isMobile(){
  if(window?.cordova?.platformId){
    return window?.cordova?.platformId == "android";
  }
  return false;
}
