import { useSelector } from "react-redux";
import { useNavigate } from "react-router-dom";
import { SUBSCRIPTION_PATH } from "../utility/path";
import "../HomeB.css";

// "Your account is inactive" banner for producers without a subscription (moved here from CustomLogo).
const InactiveBanner = () => {
  const navigate = useNavigate();
  const authData = useSelector((state) => state?.auth?.data);

  if (!(authData?.isLoggedIn && authData?.role === "producer" && !authData?.subscribed)) {
    return null;
  }

  return (
    <button type="button" className="hb-inactive" onClick={() => navigate(SUBSCRIPTION_PATH)}>
      <i className="fa fa-exclamation-circle" aria-hidden="true" />
      <span className="hb-inactive__text">Your account is inactive.</span>
      <span className="hb-inactive__cta">Subscribe to activate →</span>
    </button>
  );
};

export default InactiveBanner;
