// Groups for the home page category chips and the search popup.
// Groups are managed by admins (API /api/categorygroups/list) and each category has a `group` id.
// The built-in lists below are only a fallback: used when no groups come from the API
// (e.g. before the seed script has been run, or if the API can't be reached).

export const CATEGORY_GROUPS = [
  { key: "home",   label: "Home repair", keywords: ["carpenter", "electrician", "plumber", "airconditioner", "ac technician", "water filter", "fridge", "washing machine", "pest control", "interior", "painter", "wallpaper"] },
  { key: "beauty", label: "Beauty",      keywords: ["mehendi", "makeup", "hair", "tailor", "fashion", "embroidery"] },
  { key: "events", label: "Events",      keywords: ["event", "photographer", "videographer", "dj", "music", "choreographer", "dance", "magic", "balloon", "banner"] },
  { key: "tech",   label: "Tech",        keywords: ["cctv", "led", "tv technician", "computer", "laptop"] },
];

export const OTHER_GROUP = { key: "other", label: "Other" };

const groupIdOf = (category) => {
  const g = category?.group;
  if (!g) return null;
  return typeof g === "object" ? String(g.id || g._id || "") || null : String(g);
};

// Built-in fallback: group worked out from the category name
const builtInGroupKey = (category) => {
  const name = String(category?.name || "").toLowerCase();
  const match = CATEGORY_GROUPS.find((g) => g.keywords.some((k) => name.includes(k)));
  return match ? match.key : OTHER_GROUP.key;
};

// Categories without a (valid, active) group go to the admin's "Other" group if there is one, else a built-in "Other" chip
const otherKeyFor = (groups) => {
  const other = groups.find((g) => String(g.name || "").trim().toLowerCase() === "other");
  return other ? String(other.id) : OTHER_GROUP.key;
};

// The chip key a category belongs to
export const getCategoryGroup = (category, groups = []) => {
  if (!groups.length) return builtInGroupKey(category);
  const id = groupIdOf(category);
  return id && groups.some((g) => String(g.id) === id) ? id : otherKeyFor(groups);
};

// Readable group name for a category (shown under its name in search)
export const getCategoryGroupLabel = (category, groups = []) => {
  const key = getCategoryGroup(category, groups);
  if (!groups.length) return [...CATEGORY_GROUPS, OTHER_GROUP].find((g) => g.key === key)?.label || "";
  return groups.find((g) => String(g.id) === key)?.name || OTHER_GROUP.label;
};

// Chips: "All" plus every group that has at least one category, in the admin's order
export const getCategoryChips = (categories = [], groups = []) => {
  const used = new Set(categories.map((c) => getCategoryGroup(c, groups)));
  const all = { key: "all", label: "All" };
  if (!groups.length) {
    return [all, ...[...CATEGORY_GROUPS, OTHER_GROUP].filter((g) => used.has(g.key))];
  }
  const chips = groups.filter((g) => used.has(String(g.id))).map((g) => ({ key: String(g.id), label: g.name }));
  if (used.has(OTHER_GROUP.key)) chips.push(OTHER_GROUP);
  return [all, ...chips];
};
