import { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { PAGE_CONSTANT, runAnalytic_v2 } from "../services/functions";
import "../categories.css";
import "../SearchB.css";
import { useDispatch, useSelector } from "react-redux";
import useImageCacheIndexedDb from "../services/useImageCacheIndexedDb";
import { getCategoryColor, getCategoryIcon } from "../utility/colorForCategoryUtils";
import { getCategoryGroupLabel } from "../utility/categoryGroups";
import useCategoryGroups from "../services/useCategoryGroups";
import { CONTACT_US_PATH } from "../utility/path";
import {
  POPULAR_CATEGORY_KEYS, addRecentCategory, clearRecentCategories, displayCategoryName,
  getRecentCategoryIds, highlightParts, searchCategories, uniqueByName
} from "../utility/categorySearch";

const SEARCH_INPUT_ID = "dynamicPlaceholderInputId"; // same id as before, used to focus the box when the popup opens

// One category row: image (or icon), name, a second line, and an arrow
const CategoryRow = ({ category, idx, name, sub, onSelect }) => {
  const { image, loading, error } = useImageCacheIndexedDb(category?.photo || null);
  const colors = getCategoryColor(idx);
  return (
    <button type="button" className="sb-row" onClick={() => onSelect(category)}>
      <span className="sb-row__img" style={{ background: colors.bg }} aria-hidden="true">
        {category?.photo && image && !loading && !error
          ? <img src={image} alt="" decoding="async" />
          : <i className={`fa ${getCategoryIcon(category?.name)}`} style={{ color: colors.text }} />}
      </span>
      <span className="sb-row__text">
        <span className="sb-row__name">{name}</span>
        {sub && <span className="sb-row__sub">{sub}</span>}
      </span>
      <i className="fa fa-chevron-right sb-row__chevron" aria-hidden="true" />
    </button>
  );
};

const SearchModel = ({ handleClick }) => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const authData = useSelector(state => state?.auth?.data);
  const categories = useSelector(state => state?.categories?.data);
  const groups = useCategoryGroups();

  const [enteredValue, setEnteredValue] = useState("");
  const [recentIds, setRecentIds] = useState(getRecentCategoryIds);

  // Unique categories, A–Z ("user" and duplicate names left out)
  const allCategories = useMemo(
    () => uniqueByName(categories || []).sort((a, b) => displayCategoryName(a.name).localeCompare(displayCategoryName(b.name))),
    [categories]
  );
  const popular = useMemo(
    () => POPULAR_CATEGORY_KEYS.map((k) => allCategories.find((c) => c.name.toLowerCase().includes(k))).filter(Boolean),
    [allCategories]
  );
  const recent = useMemo(
    () => recentIds.map((id) => allCategories.find((c) => c.id === id)).filter(Boolean),
    [recentIds, allCategories]
  );
  const results = useMemo(() => searchCategories(allCategories, enteredValue), [allCategories, enteredValue]);

  const handleChange = (e) => {
    e.preventDefault();
    runAnalytic_v2({ categoryToAdd: e?.target?.value, authData, dispatch, page: PAGE_CONSTANT.SEARCH_PAGE });
    setEnteredValue(e.target.value);
  };

  const selectCategory = (category) => {
    runAnalytic_v2({ categoryToAdd: category?.name, authData, dispatch, page: PAGE_CONSTANT.SEARCH_PAGE, searchCategoryId: category?.id });
    addRecentCategory(category?.id);
    setRecentIds(getRecentCategoryIds());
    handleCloseModal();
    handleClick(category);
  };

  const clearRecent = () => {
    clearRecentCategories();
    setRecentIds([]);
  };

  const tellUs = () => {
    handleCloseModal();
    navigate(CONTACT_US_PATH);
  };

  const handleCloseModal = async () => {
    $('#searchModal').modal('hide');

    const modalElementHeader = document.getElementById('header');
    modalElementHeader?.classList?.remove('hidden');

    // Clean up any leftover backdrop (Bootstrap 4)
    const modalElements = document.getElementsByClassName('modal-backdrop');
    if (modalElements?.length > 0) {
      Array.from(modalElements).forEach((el) => el.classList.remove('modal-backdrop'));
      Array.from(document.getElementsByClassName('modal')).forEach((modal) => {
        modal.classList.remove('show');
        modal.style.display = 'none';
      });
      $('body').removeClass('modal-open');
      $('.modal-backdrop').remove();
    }
  };

  useEffect(() => {
    const modalElement = document.getElementById('searchModal');
    $(modalElement).on('shown.bs.modal', function () {
      const inputElement = document.getElementById(SEARCH_INPUT_ID);
      if (inputElement) {
        document.getElementById('header')?.classList?.add('hidden');
        inputElement.focus(); // focus the box after the popup opens
      }
      setRecentIds(getRecentCategoryIds());
    });
    return () => { handleCloseModal(); };
  }, []);

  const groupLabel = (category) => getCategoryGroupLabel(category, groups);

  const renderName = (category) => {
    const name = displayCategoryName(category?.name);
    const [before, match, after] = highlightParts(name, enteredValue);
    return match ? <>{before}<mark className="sb-mark">{match}</mark>{after}</> : name;
  };

  const popularChips = popular.length > 0 && (
    <>
      <h2 className="sb-label">Popular</h2>
      <div className="sb-chips">
        {popular.map((c) => (
          <button key={c.id} type="button" className="sb-chip" onClick={() => selectCategory(c)}>{displayCategoryName(c.name)}</button>
        ))}
      </div>
    </>
  );

  return (
    <div className="modal fade" id="searchModal" role="dialog" aria-label="Search services" aria-hidden="true" tabIndex="-1">
      <div className="modal-dialog modal-fullscreen" role="document">
        <div className="modal-content">
          <div className="col-md-6 offset-md-3 px-0 sb-panel">
            <div className="sb-header">
              <button type="button" className="sb-back" onClick={handleCloseModal} aria-label="Back">
                <i className="fa fa-arrow-left" aria-hidden="true" />
              </button>
              <label className="sb-field">
                <i className="fa fa-search sb-field__icon" aria-hidden="true" />
                <input
                  id={SEARCH_INPUT_ID}
                  type="text"
                  className="sb-input"
                  placeholder="Search plumber, electrician, AC…"
                  aria-label="Search services"
                  autoComplete="off"
                  value={enteredValue}
                  onChange={handleChange}
                />
                {enteredValue && (
                  <button type="button" className="sb-clear" onClick={() => setEnteredValue("")} aria-label="Clear search">&times;</button>
                )}
              </label>
            </div>

            <div className="sb-body">
              {!enteredValue.trim() ? (
                <>
                  {recent.length > 0 && (
                    <>
                      <div className="sb-label-row">
                        <h2 className="sb-label">Recent searches</h2>
                        <button type="button" className="sb-link" onClick={clearRecent}>Clear</button>
                      </div>
                      {recent.map((c) => (
                        <button key={c.id} type="button" className="sb-recent" onClick={() => selectCategory(c)}>
                          <i className="fa fa-clock-o" aria-hidden="true" />
                          <span className="sb-recent__name">{displayCategoryName(c.name)}</span>
                          <i className="fa fa-chevron-right sb-row__chevron" aria-hidden="true" />
                        </button>
                      ))}
                    </>
                  )}

                  {popularChips}

                  <h2 className="sb-label">All categories · A–Z</h2>
                  {allCategories.map((c, i) => (
                    <CategoryRow key={c.id} category={c} idx={i} name={displayCategoryName(c.name)} sub={groupLabel(c)} onSelect={selectCategory} />
                  ))}
                </>
              ) : (
                <>
                  <p className="sb-count" aria-live="polite">{results.length === 1 ? "1 result" : `${results.length} results`}</p>
                  {results.map(({ category, via, keyword, examples }, i) => (
                    <CategoryRow
                      key={category.id}
                      category={category}
                      idx={i}
                      name={renderName(category)}
                      sub={via === "keyword"
                        ? <>Matches “<mark className="sb-mark">{keyword}</mark>”{examples?.length ? ` · ${examples.join(", ")}` : ""}</>
                        : groupLabel(category)}
                      onSelect={selectCategory}
                    />
                  ))}

                  <div className="sb-cantfind">
                    <p className="sb-cantfind__title">Can't find what you need?</p>
                    <p className="sb-cantfind__text">Tell us the service and we'll look for professionals near you.</p>
                    <button type="button" className="sb-cantfind__btn" onClick={tellUs}>Tell us what you need</button>
                  </div>

                  {popularChips}
                </>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default SearchModel;
